"""Isolated analysis process; all paths are generated by the backend."""
import json
import sys
import traceback
from pathlib import Path
import joblib
from .engine import analyze
from .config import AnalysisConfig


def main():
    work=Path(sys.argv[1]);config=json.loads(sys.stdin.read())
    try:
        result,models=analyze(work/'dataset.csv',AnalysisConfig(**config),filename='uploaded.csv')
        (work/'result.json').write_text(json.dumps(result,ensure_ascii=False,allow_nan=False),encoding='utf-8')
        joblib.dump(models,work/'models.joblib')
    except Exception as exc:
        (work/'error.json').write_text(json.dumps({'detail':str(exc)}),encoding='utf-8')
        sys.exit(1)


if __name__=='__main__':main()
